  const rows = await all(
    "SELECT asked_at FROM demo_usage WHERE client = ? AND asked_at >= ? ORDER BY asked_at ASC",
    [client3, since]
  );
  const used = rows.length;
  const oldest = rows[0]?.asked_at;
  const retryAfterMinutes = oldest ? Math.max(1, Math.ceil((new Date(oldest).getTime() + WINDOW_MS - Date.now()) / 6e4)) : 0;
